import 'package:auto_shop_server/app/utils/common_widget/common_widget.dart';import 'package:auto_shop_server/app/utils/global.dart';import 'package:auto_shop_server/res/assets_res.dart';import 'package:flutter/material.dart';import 'package:shimmer/shimmer.dart';class HomeSkeletonItem extends StatelessWidget {  const HomeSkeletonItem({super.key});  @override  Widget build(BuildContext context) {    final themeData = Theme.of(context);    final backgroundColor = themeData.colorScheme.surfaceContainerHighest;    final foregroundColor = themeData.colorScheme.surface;    return Card(      elevation: 0,      margin: EdgeInsets.zero,      child: Column(        mainAxisAlignment: MainAxisAlignment.center,        children: [          Shimmer.fromColors(            // baseColor: Colors.grey[300]!, // 闪烁效果的底色            // highlightColor: Colors.grey[100]!, // 闪烁效果的高亮部分颜色            baseColor: backgroundColor,            highlightColor: foregroundColor,            child: Row(              mainAxisAlignment: MainAxisAlignment.spaceEvenly,              children: [                ClipOval(                  child: imageAsset(AssetsRes.PLACEHOLDER_115, width: 50 , fit: BoxFit.fill),                ),                Column(                  crossAxisAlignment: CrossAxisAlignment.start,                  children: [                    Container(color: Colors.grey[200], width: 80, height: 15),                    const SizedBox(height: 6),                    Container(color: Colors.grey[200], width: 60, height: 12),                    const SizedBox(height: 6),                    Container(color: Colors.grey[200], width: 50, height: 12),                  ],                )              ],            ),          ),        ]      )    );  }}